+pub type Path64 = Vec<Point64>;
+pub type Paths64 = Vec<Path64>;
+
+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+pub struct Point64 {
+    pub x: i64,
+    pub y: i64,
+}
+
+impl Point64 {
+    pub const fn new(x: i64, y: i64) -> Self {
+        Self { x, y }
+    }
+}
+
+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+pub struct Rect64 {
+    pub left: i64,
+    pub top: i64,
+    pub right: i64,
+    pub bottom: i64,
+}
+
+impl Rect64 {
+    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
+        Self {
+            left,
+            top,
+            right,
+            bottom,
+        }
+    }
+}
+
+pub fn area(path: &Path64) -> f64 {
+    if path.len() < 3 {
+        return 0.0;
+    }
+
+    let mut sum: i128 = 0;
+    for i in 0..path.len() {
+        let j = (i + 1) % path.len();
+        sum += path[i].x as i128 * path[j].y as i128;
+        sum -= path[i].y as i128 * path[j].x as i128;
+    }
+    (sum.abs() as f64) / 2.0
+}
+
+pub fn get_bounds(paths: &Paths64) -> Rect64 {
+    let mut found = false;
+    let mut left = 0_i64;
+    let mut top = 0_i64;
+    let mut right = 0_i64;
+    let mut bottom = 0_i64;
+
+    for path in paths {
+        for point in path {
+            if !found {
+                left = point.x;
+                right = point.x;
+                top = point.y;
+                bottom = point.y;
+                found = true;
+                continue;
+            }
+            left = left.min(point.x);
+            right = right.max(point.x);
+            top = top.min(point.y);
+            bottom = bottom.max(point.y);
+        }
+    }
+
+    if !found {
+        Rect64::new(0, 0, 0, 0)
+    } else {
+        Rect64::new(left, top, right, bottom)
+    }
+}
