+pub fn format_cpp_default(value: f64) -> String {
+    if value == 0.0 {
+        return String::from("0");
+    }
+
+    let precision = 6_i32;
+    let exponent = value.abs().log10().floor() as i32;
+
+    if exponent < -4 || exponent >= precision {
+        return format_scientific(value, (precision - 1) as usize);
+    }
+
+    let digits_after_decimal = (precision - exponent - 1).max(0) as usize;
+    let mut fixed = format!("{:.*}", digits_after_decimal, value);
+    trim_trailing_zeros(&mut fixed);
+
+    let rounded_value = fixed.parse::<f64>().unwrap_or(value);
+    let rounded_exponent = if rounded_value == 0.0 {
+        0
+    } else {
+        rounded_value.abs().log10().floor() as i32
+    };
+
+    if rounded_exponent >= precision {
+        format_scientific(value, (precision - 1) as usize)
+    } else {
+        fixed
+    }
+}
+
+fn format_scientific(value: f64, digits_after_decimal: usize) -> String {
+    let scientific = format!("{:.*e}", digits_after_decimal, value);
+    let (mantissa, exponent) = scientific.split_once('e').unwrap();
+    let mut mantissa = mantissa.to_string();
+    trim_trailing_zeros(&mut mantissa);
+
+    let exponent_value = exponent.parse::<i32>().unwrap();
+    let sign = if exponent_value >= 0 { '+' } else { '-' };
+    let magnitude = exponent_value.abs();
+    format!("{mantissa}e{sign}{magnitude:02}")
+}
+
+fn trim_trailing_zeros(value: &mut String) {
+    if !value.contains('.') {
+        return;
+    }
+
+    while value.ends_with('0') {
+        value.pop();
+    }
+    if value.ends_with('.') {
+        value.pop();
+    }
+}
