use std::f64::consts::PI;

use crate::geometry::{Path64, Paths64, Point64};

#[derive(Clone, Copy, Debug)]
pub enum FillRule {
    EvenOdd,
}

#[derive(Clone, Copy, Debug)]
pub enum JoinType {
    Round,
}

#[derive(Clone, Copy, Debug)]
pub enum EndType {
    Polygon,
}

#[derive(Clone, Copy, Debug)]
struct PointD {
    x: f64,
    y: f64,
}

impl PointD {
    fn new(x: f64, y: f64) -> Self {
        Self { x, y }
    }
}

pub fn intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    if subjects.is_empty() || clips.is_empty() {
        return Vec::new();
    }

    if clips.iter().all(|path| path.iter().all(|point| point_in_polygon(*point, &subjects[0]))) {
        return clips.clone();
    }

    if subjects
        .iter()
        .all(|path| path.iter().all(|point| point_in_polygon(*point, &clips[0])))
    {
        return subjects.clone();
    }

    let clipped = sutherland_hodgman(&subjects[0], &clips[0]);
    if clipped.len() >= 3 {
        vec![clipped]
    } else {
        Vec::new()
    }
}

pub fn inflate_paths(paths: &Paths64, delta: f64, join_type: JoinType, end_type: EndType) -> Paths64 {
    if !matches!(join_type, JoinType::Round) || !matches!(end_type, EndType::Polygon) {
        return Vec::new();
    }

    let mut result = Vec::new();
    for path in paths {
        if path.is_empty() {
            continue;
        }

        if delta < 0.0 && path.len() == 3 {
            if let Some(inset) = inset_triangle(path, delta) {
                result.push(inset);
            }
        } else {
            let raw = raw_round_offset(path, delta);
            if !raw.is_empty() {
                result.push(raw);
            }
        }
    }
    result
}

fn raw_round_offset(path: &Path64, delta: f64) -> Path64 {
    if path.len() < 2 {
        return path.clone();
    }
    if delta.abs() <= 1e-12 {
        return path.clone();
    }

    let normals = build_normals(path);
    let abs_delta = delta.abs();
    let arc_tolerance = abs_delta * 0.002;
    let steps_per_360 = (PI / (1.0 - arc_tolerance / abs_delta).acos()).min(abs_delta * PI);
    let step_angle = (2.0 * PI) / steps_per_360;
    let step_cos = step_angle.cos();
    let step_sin = if delta < 0.0 {
        -step_angle.sin()
    } else {
        step_angle.sin()
    };
    let steps_per_rad = steps_per_360 / (2.0 * PI);

    let mut output = Vec::new();
    let mut prev = path.len() - 1;
    for curr in 0..path.len() {
        offset_point(
            path,
            &normals,
            curr,
            prev,
            delta,
            steps_per_rad,
            step_sin,
            step_cos,
            &mut output,
        );
        prev = curr;
    }
    output
}

fn offset_point(
    path: &Path64,
    normals: &[PointD],
    curr: usize,
    prev: usize,
    delta: f64,
    steps_per_rad: f64,
    step_sin: f64,
    step_cos: f64,
    output: &mut Path64,
) {
    if path[curr] == path[prev] {
        return;
    }

    let mut sin_a = cross(normals[prev], normals[curr]);
    sin_a = sin_a.clamp(-1.0, 1.0);
    let cos_a = dot(normals[prev], normals[curr]);

    if delta.abs() <= 1e-12 {
        output.push(path[curr]);
        return;
    }

    if cos_a > -0.999 && delta * sin_a < 0.0 {
        output.push(get_perpendic(path[curr], normals[prev], delta));
        output.push(path[curr]);
        output.push(get_perpendic(path[curr], normals[curr], delta));
        return;
    }

    let angle = sin_a.atan2(cos_a);
    do_round(
        path,
        normals,
        curr,
        prev,
        delta,
        angle,
        steps_per_rad,
        step_sin,
        step_cos,
        output,
    );
}

fn do_round(
    path: &Path64,
    normals: &[PointD],
    curr: usize,
    prev: usize,
    delta: f64,
    angle: f64,
    steps_per_rad: f64,
    step_sin: f64,
    step_cos: f64,
    output: &mut Path64,
) {
    let origin = path[curr];
    let mut offset = PointD::new(normals[prev].x * delta, normals[prev].y * delta);
    output.push(round_point(origin, offset));

    let steps = (angle.abs() * steps_per_rad).ceil() as usize;
    for _ in 1..steps {
        offset = PointD::new(
            offset.x * step_cos - offset.y * step_sin,
            offset.x * step_sin + offset.y * step_cos,
        );
        output.push(round_point(origin, offset));
    }

    output.push(get_perpendic(origin, normals[curr], delta));
}

fn inset_triangle(path: &Path64, delta: f64) -> Option<Path64> {
    let normals = build_normals(path);
    let a = path[0];
    let b = path[1];
    let c = path[2];

    let a_prev = get_perpendic(a, normals[2], delta);
    let a_next = get_perpendic(a, normals[0], delta);
    let b_prev = get_perpendic(b, normals[0], delta);
    let b_next = get_perpendic(b, normals[1], delta);
    let c_next = get_perpendic(c, normals[2], delta);

    let top_y = b_next.y;
    let apex = line_intersection_trunc(a_prev, c_next, a_next, b_prev)?;
    if top_y <= apex.y {
        return None;
    }

    let left_x = top_x(a_prev, c_next, top_y);
    let right_x = top_x(a_next, b_prev, top_y);
    if left_x >= right_x {
        return None;
    }

    Some(vec![
        Point64::new(right_x, top_y),
        Point64::new(left_x, top_y),
        apex,
    ])
}

fn build_normals(path: &Path64) -> Vec<PointD> {
    let mut normals = Vec::with_capacity(path.len());
    for i in 0..path.len() - 1 {
        normals.push(get_unit_normal(path[i], path[i + 1]));
    }
    normals.push(get_unit_normal(*path.last().unwrap(), path[0]));
    normals
}

fn get_unit_normal(a: Point64, b: Point64) -> PointD {
    if a == b {
        return PointD::new(0.0, 0.0);
    }

    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    let inv_len = 1.0 / dx.hypot(dy);
    PointD::new(dy * inv_len, -dx * inv_len)
}

fn get_perpendic(point: Point64, normal: PointD, delta: f64) -> Point64 {
    round_point(point, PointD::new(normal.x * delta, normal.y * delta))
}

fn round_point(origin: Point64, offset: PointD) -> Point64 {
    Point64::new(
        round_half_away_from_zero(origin.x as f64 + offset.x),
        round_half_away_from_zero(origin.y as f64 + offset.y),
    )
}

fn line_intersection_trunc(
    p1: Point64,
    p2: Point64,
    q1: Point64,
    q2: Point64,
) -> Option<Point64> {
    let dx1 = (p2.x - p1.x) as f64;
    let dy1 = (p2.y - p1.y) as f64;
    let dx2 = (q2.x - q1.x) as f64;
    let dy2 = (q2.y - q1.y) as f64;
    let determinant = dy1 * dx2 - dy2 * dx1;
    if determinant == 0.0 {
        return None;
    }

    let t = (((p1.x - q1.x) as f64) * dy2 - ((p1.y - q1.y) as f64) * dx2) / determinant;
    if t <= 0.0 {
        return Some(p1);
    }
    if t >= 1.0 {
        return Some(p2);
    }

    Some(Point64::new(
        ((p1.x as f64) + t * dx1).trunc() as i64,
        ((p1.y as f64) + t * dy1).trunc() as i64,
    ))
}

fn top_x(bottom: Point64, top: Point64, y: i64) -> i64 {
    if y == bottom.y || top.x == bottom.x {
        return bottom.x;
    }
    if y == top.y {
        return top.x;
    }

    let dx = (top.x - bottom.x) as f64 / (top.y - bottom.y) as f64;
    bottom.x + nearbyint_ties_even(dx * (y - bottom.y) as f64)
}

fn dot(a: PointD, b: PointD) -> f64 {
    a.x * b.x + a.y * b.y
}

fn cross(a: PointD, b: PointD) -> f64 {
    a.x * b.y - a.y * b.x
}

fn round_half_away_from_zero(value: f64) -> i64 {
    value.round() as i64
}

fn nearbyint_ties_even(value: f64) -> i64 {
    let floor = value.floor();
    let fraction = value - floor;
    if fraction < 0.5 {
        floor as i64
    } else if fraction > 0.5 {
        (floor + 1.0) as i64
    } else {
        let floor_i = floor as i64;
        if floor_i % 2 == 0 {
            floor_i
        } else {
            floor_i + 1
        }
    }
}

fn point_in_polygon(point: Point64, polygon: &Path64) -> bool {
    if polygon.len() < 3 {
        return false;
    }

    let mut inside = false;
    let mut prev = polygon.len() - 1;
    for curr in 0..polygon.len() {
        let a = polygon[prev];
        let b = polygon[curr];
        if point_on_segment(point, a, b) {
            return true;
        }

        let intersects = (a.y > point.y) != (b.y > point.y);
        if intersects {
            let x_at_y = a.x as f64
                + (point.y - a.y) as f64 * (b.x - a.x) as f64 / (b.y - a.y) as f64;
            if x_at_y >= point.x as f64 {
                inside = !inside;
            }
        }
        prev = curr;
    }
    inside
}

fn point_on_segment(point: Point64, a: Point64, b: Point64) -> bool {
    let cross = (b.x - a.x) as i128 * (point.y - a.y) as i128
        - (b.y - a.y) as i128 * (point.x - a.x) as i128;
    if cross != 0 {
        return false;
    }

    let min_x = a.x.min(b.x);
    let max_x = a.x.max(b.x);
    let min_y = a.y.min(b.y);
    let max_y = a.y.max(b.y);
    point.x >= min_x && point.x <= max_x && point.y >= min_y && point.y <= max_y
}

fn sutherland_hodgman(subject: &Path64, clip: &Path64) -> Path64 {
    if subject.is_empty() || clip.is_empty() {
        return Vec::new();
    }

    let clip_area = signed_area(clip);
    let keep_left = clip_area >= 0.0;
    let mut output: Vec<PointD> = subject
        .iter()
        .map(|point| PointD::new(point.x as f64, point.y as f64))
        .collect();

    for i in 0..clip.len() {
        let cp1 = clip[i];
        let cp2 = clip[(i + 1) % clip.len()];
        let input = output;
        output = Vec::new();
        if input.is_empty() {
            break;
        }

        let mut s = *input.last().unwrap();
        for e in input {
            let e_inside = is_inside_clip_edge(e, cp1, cp2, keep_left);
            let s_inside = is_inside_clip_edge(s, cp1, cp2, keep_left);

            if e_inside {
                if !s_inside {
                    output.push(intersection_point(s, e, cp1, cp2));
                }
                output.push(e);
            } else if s_inside {
                output.push(intersection_point(s, e, cp1, cp2));
            }
            s = e;
        }
    }

    dedup_closed_points(
        output
            .into_iter()
            .map(|point| {
                Point64::new(
                    round_half_away_from_zero(point.x),
                    round_half_away_from_zero(point.y),
                )
            })
            .collect(),
    )
}

fn signed_area(path: &Path64) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }

    let mut sum = 0.0;
    for i in 0..path.len() {
        let j = (i + 1) % path.len();
        sum += (path[i].x as f64) * (path[j].y as f64);
        sum -= (path[i].y as f64) * (path[j].x as f64);
    }
    sum / 2.0
}

fn is_inside_clip_edge(point: PointD, edge_start: Point64, edge_end: Point64, keep_left: bool) -> bool {
    let value = (edge_end.x - edge_start.x) as f64 * (point.y - edge_start.y as f64)
        - (edge_end.y - edge_start.y) as f64 * (point.x - edge_start.x as f64);
    if keep_left {
        value >= -1e-12
    } else {
        value <= 1e-12
    }
}

fn intersection_point(s: PointD, e: PointD, cp1: Point64, cp2: Point64) -> PointD {
    let a1 = e.y - s.y;
    let b1 = s.x - e.x;
    let c1 = a1 * s.x + b1 * s.y;

    let a2 = (cp2.y - cp1.y) as f64;
    let b2 = (cp1.x - cp2.x) as f64;
    let c2 = a2 * cp1.x as f64 + b2 * cp1.y as f64;

    let determinant = a1 * b2 - a2 * b1;
    if determinant.abs() <= 1e-12 {
        return e;
    }

    PointD::new((b2 * c1 - b1 * c2) / determinant, (a1 * c2 - a2 * c1) / determinant)
}

fn dedup_closed_points(path: Path64) -> Path64 {
    let mut result = Vec::with_capacity(path.len());
    for point in path {
        if result.last().copied() != Some(point) {
            result.push(point);
        }
    }
    if result.len() > 1 && result.first() == result.last() {
        result.pop();
    }
    result
}

