    if path.len() < 3 {
        return 0.0;
    }

    let mut sum = 0.0;
    for i in 0..path.len() {
        let j = (i + 1) % path.len();
        sum += (path[i].x as f64) * (path[j].y as f64);
        sum -= (path[i].y as f64) * (path[j].x as f64);
