    let c1 = a1 * s.x + b1 * s.y;

    let a2 = (cp2.y - cp1.y) as f64;
    let b2 = (cp1.x - cp2.x) as f64;
    let c2 = a2 * cp1.x as f64 + b2 * cp1.y as f64;

    let determinant = a1 * b2 - a2 * b1;
    if determinant.abs() <= 1e-12 {
        return e;
    }

    PointD::new((b2 * c1 - b1 * c2) / determinant, (a1 * c2 - a2 * c1) / determinant)
}

fn dedup_closed_points(path: Path64) -> Path64 {
    let mut result = Vec::with_capacity(path.len());
    for point in path {
        if result.last().copied() != Some(point) {
            result.push(point);
        }
    }
    if result.len() > 1 && result.first() == result.last() {
        result.pop();
    }
    result
}

